'use strict';
const K=CleanCore;
state.cleanData=null;state.cleanEdits=[];state.cleanFormat='xlsx';state.cleanReviewed=false;
function cleanText(key,args=[]){return I18n.t('clean.'+key,args);}
function cleanSetData(d,name){state.cleanData={...d,name,isDemo:false,headers:[...d.headers],rows:d.rows.map(row=>[...row]),types:ImportCore.infer(d)};state.cleanEdits=d.headers.map(name=>({name,type:'preserve'}));state.cleanReviewed=false;}
function openCleanFromCurrent(){if(!K.canUse('cleanExport'))return toast(cleanText('disabled'));const d=activeData();if(!d)return navigate('clean');const source={workbook:state.workbook,raw:state.raw,headerRow:state.headerRow,hasHeader:state.hasHeader,headerDetection:state.headerDetection,sheet:state.sheet,appliedPreset:'',restoreNote:''};cleanSetData(d,d.name);state.cleanData.isDemo=!!d.isDemo;state.imports.clean=source;navigate('clean');}
function cleanPrepared(){return K.prepare(state.cleanData,state.cleanEdits,{format:state.cleanFormat,sourceSheet:state.workbook?.Sheets[state.sheet],X:XLSX});}
function cleanPreview(headers,rows,start=0,original=false){return `<div class="table-wrap clean-table"><table><thead><tr><th>${cleanText(original?'row':'rawRow')}</th>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,12).map((row,i)=>`<tr><th>${i+start+1}</th>${headers.map((_,j)=>`<td>${esc(row[j]??'')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function renderClean(){const d=state.cleanData;$('#workspace').innerHTML=loadPanel();bindLoad();if(!K.canUse('cleanExport')){$('#workspace').insertAdjacentHTML('beforeend',`<div class="notice">${cleanText('disabled')}</div>`);return;}
  if(!d){$('#workspace').insertAdjacentHTML('beforeend',`<div class="notice neutral">${cleanText('empty')}</div>`);return;}
  const p=cleanPrepared(),raw=state.raw||[d.headers,...d.rows],types=d.types||ImportCore.infer(d),format=state.cleanFormat;
  $('#workspace').insertAdjacentHTML('beforeend',`<section class="panel"><div class="panel-head"><h2><span class="step">02</span>${cleanText('columns')}</h2><button id="clean-reset">${cleanText('reset')}</button></div><p>${cleanText('typesNote')}</p><details class="clean-column-settings"><summary>${cleanText('columns')} · ${d.headers.length}</summary><div class="table-wrap"><table><thead><tr><th>${cleanText('column')}</th><th>${cleanText('name')}</th><th>${cleanText('inferred')}</th><th>${cleanText('type')}</th></tr></thead><tbody>${d.headers.map((h,i)=>`<tr><td>${esc(h)}</td><td><input data-clean-name="${i}" aria-label="${esc(cleanText('name'))} ${i+1}" value="${esc(state.cleanEdits[i].name)}" maxlength="200"></td><td>${cleanText({number:'numberHint',date:'dateHint',category:'category'}[types[i].type])}</td><td><select data-clean-type="${i}" aria-label="${esc(cleanText('type'))} ${i+1}">${['preserve','text','number','date'].map(v=>`<option value="${v}" ${state.cleanEdits[i].type===v?'selected':''}>${cleanText(v)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div></details></section><section class="panel"><div class="panel-head"><h2><span class="step">03</span>${cleanText('cleaned')}</h2><div><label for="clean-format">${cleanText('format')}</label><select id="clean-format"><option value="xlsx" ${format==='xlsx'?'selected':''}>Excel (.xlsx)</option><option value="csv" ${format==='csv'?'selected':''}>CSV (.csv)</option></select></div></div><p>${cleanText('structure',[d.sourceHeaderRow||1])}</p><p>${cleanText('noStatistics')}</p><p class="restore-note" id="clean-changes">${cleanText('changes',Object.values(p.changes))}</p><p class="section-note">${cleanText('previewNote',[12,p.rows.length,p.headers.length])}</p><div class="clean-comparison"><div><h3>${cleanText('original')}</h3>${cleanPreview(d.headers.map((_,i)=>XLSX.utils.encode_col(i)),raw,0,true)}</div><div><h3>${cleanText('cleaned')}</h3>${cleanPreview(p.headers,p.rows,p.sourceStart)}</div></div>${format==='csv'?`<p class="notice neutral">${cleanText('csvNote')}</p>${p.formulaLike?`<p class="notice">${cleanText('formulaWarning',[p.formulaLike])}</p>`:''}`:''}${p.issues.length?`<div class="notice error" role="alert"><p>${cleanText('issues',[p.issues.length])}</p><ul>${p.issues.slice(0,20).map(issue=>`<li>${cleanText('issue.location',[issue.row===null?'—':p.sourceStart+issue.row+1,issue.column+1,cleanText('issue.'+issue.code)])}</li>`).join('')}</ul></div>`:''}<div class="clean-export-bar"><div><label>${cleanText('filename')}</label><strong id="clean-filename">${esc(K.filename(d.name,format))}</strong></div><label class="check"><input id="clean-reviewed" type="checkbox" ${state.cleanReviewed?'checked':''}>${cleanText('review')}</label><button id="clean-export" class="primary" ${p.issues.length||!state.cleanReviewed?'disabled':''}>${cleanText('export')}</button></div></section>`);
  $$('[data-clean-name]').forEach(el=>el.onchange=()=>{state.cleanEdits[+el.dataset.cleanName].name=el.value;state.cleanReviewed=false;renderClean();$('.clean-column-settings').open=true;});
  $$('[data-clean-type]').forEach(el=>el.onchange=()=>{state.cleanEdits[+el.dataset.cleanType].type=el.value;state.cleanReviewed=false;renderClean();$('.clean-column-settings').open=true;});
  $('#clean-format').onchange=e=>{state.cleanFormat=e.target.value;state.cleanReviewed=false;renderClean();};
  $('#clean-reset').onclick=()=>{state.cleanEdits=d.headers.map(name=>({name,type:'preserve'}));state.cleanReviewed=false;renderClean();};
  $('#clean-reviewed').onchange=e=>{state.cleanReviewed=e.target.checked;$('#clean-export').disabled=!state.cleanReviewed||p.issues.length>0;};
  $('#clean-export').onclick=()=>safe(exportClean);
}
function exportClean(){if(!K.canUse('cleanExport'))throw Error(cleanText('disabled'));if(!state.cleanReviewed)throw Error(cleanText('confirmRequired'));const p=cleanPrepared();if(p.issues.length)throw Error(cleanText('blocked'));const format=state.cleanFormat,name=K.filename(state.cleanData.name,format);if(format==='csv')saveBlob(K.csv(p),name,'text/csv;charset=utf-8');else saveBlob(XLSX.write(K.workbook(XLSX,p),{type:'array',bookType:'xlsx'}),name,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');toast(cleanText('saved'));}
